"""Koko Eating Bananas — binary search on the eating speed.

"Can she finish at speed k?" is monotonic in k, so search the smallest feasible
speed in [1, max(piles)].

Time: O(n log max(piles))   Space: O(1)
"""
from typing import List


class Solution:
    def minEatingSpeed(self, piles: List[int], h: int) -> int:
        def hours(speed: int) -> int:
            return sum((pile + speed - 1) // speed for pile in piles)

        lo, hi = 1, max(piles)
        while lo < hi:
            mid = (lo + hi) // 2
            if hours(mid) <= h:
                hi = mid
            else:
                lo = mid + 1
        return lo
